//! Rust `run_search` replays the TypeScript `search()` vectors
//! (web_search_query_ts_vectors.json, generated by searchQueryVectors.test.ts
//! from the exact ingest entries and query input the Rust-mode page sends), plus
//! wire decoding refusals and the encoded row layout.
use crate::web_search_chats::{ChatSearchIndex, EntryMeta, IngestEntry};
use crate::web_search_query::*;
use serde_json::{json, Map, Value};

fn vectors() -> Value {
    serde_json::from_str(include_str!("web_search_query_ts_vectors.json")).unwrap()
}

fn text(value: &Value) -> Option<String> {
    value.as_str().map(str::to_owned)
}

fn ingest_entry(item: &Value) -> IngestEntry {
    let meta = EntryMeta {
        source_label: text(&item["embedSourceLabel"]),
        embed_id: text(&item["embedId"]),
        embed_type: text(&item["embedType"]),
        title: text(&item["embedTitle"]),
        subtitle: text(&item["embedSubtitle"]),
        app_id: text(&item["embedAppId"]),
        skill_id: text(&item["embedSkillId"]),
        focus_id: text(&item["embedFocusId"]),
        focus_mode_name: text(&item["embedFocusModeName"]),
    };
    IngestEntry {
        message_id: item["messageId"].as_str().unwrap().into(),
        content: item["content"].as_str().unwrap().into(),
        created_at: item["createdAt"].as_f64().unwrap(),
        meta: (meta != EntryMeta::default()).then_some(meta),
    }
}

fn catalog(entries: &Value, kind: CatalogKind) -> Vec<CatalogEntry> {
    entries
        .as_array()
        .unwrap()
        .iter()
        .map(|entry| CatalogEntry {
            kind,
            access: match entry["access"].as_str() {
                None | Some("public") => CatalogAccess::Public,
                Some("authenticated") => CatalogAccess::Authenticated,
                Some("admin") => CatalogAccess::Admin,
                Some(other) => panic!("unknown access {other}"),
            },
            label: entry["label"].as_str().unwrap().into(),
            keywords: entry["keywords"]
                .as_array()
                .unwrap()
                .iter()
                .map(|k| k.as_str().unwrap().into())
                .collect(),
        })
        .collect()
}

/// JSON object without the `None` fields (JSON.stringify drops `undefined`).
fn object(fields: Vec<(&str, Value)>) -> Value {
    Value::Object(
        fields
            .into_iter()
            .filter(|(_, value)| !value.is_null())
            .map(|(key, value)| (key.to_owned(), value))
            .collect::<Map<_, _>>(),
    )
}

fn meta_field(meta: Option<&EntryMeta>, field: fn(&EntryMeta) -> &Option<String>) -> Value {
    meta.and_then(|meta| field(meta).clone())
        .map_or(Value::Null, Value::String)
}

#[test]
fn search_equals_typescript() {
    let vectors = vectors();
    let mut index = ChatSearchIndex::default();
    let mut handles = std::collections::HashMap::new();
    for (n, (chat_id, entries)) in vectors["ingests"].as_object().unwrap().iter().enumerate() {
        let handle = n as u32 + 1;
        handles.insert(chat_id.clone(), handle);
        let entries = entries
            .as_array()
            .unwrap()
            .iter()
            .map(ingest_entry)
            .collect();
        assert!(index.ingest_chat(handle, entries).is_empty());
    }
    let chat_ids: Vec<String> = vectors["chats"]
        .as_array()
        .unwrap()
        .iter()
        .map(|chat| chat["chatId"].as_str().unwrap().to_owned())
        .collect();
    let chats: Vec<QueryChat> = vectors["chats"]
        .as_array()
        .unwrap()
        .iter()
        .map(|chat| QueryChat {
            handle: if chat["messages"].as_bool().unwrap() {
                handles
                    .get(chat["chatId"].as_str().unwrap())
                    .copied()
                    .unwrap_or(0)
            } else {
                0
            },
            title: text(&chat["title"]),
            active_focus_id: text(&chat["activeFocusId"]),
            summary: text(&chat["summary"]),
            tags: chat["tags"].as_array().map(|tags| {
                tags.iter()
                    .map(|tag| tag.as_str().unwrap().into())
                    .collect()
            }),
            draft: text(&chat["draft"]),
            last_edited: chat["lastEdited"].as_f64().unwrap(),
        })
        .collect();
    let settings = catalog(&vectors["settings"], CatalogKind::Settings);
    let settings_count = settings.len();
    let mut entries = settings;
    entries.extend(catalog(&vectors["apps"], CatalogKind::App));
    for case in vectors["cases"].as_array().unwrap() {
        let request = SearchQuery {
            query: case["query"].as_str().unwrap().into(),
            include_embeds: case["includeEmbeds"].as_bool().unwrap(),
            authenticated: case["isAuthenticated"].as_bool().unwrap(),
            admin: case["isAdmin"].as_bool().unwrap(),
            chats: chats.clone(),
            catalog: entries.clone(),
        };
        let outcome = run_search(&index, &request);
        let actual = json!({
            "chats": outcome.chats.iter().map(|chat| {
                let chat_id = &chat_ids[chat.position];
                json!({
                    "chatId": chat_id,
                    "titleMatchRanges": chat.title_ranges.iter().map(|range| json!({"start": range.start, "length": range.length})).collect::<Vec<_>>(),
                    "messageSnippets": chat.messages.iter().map(|hit| object(vec![
                        ("messageId", json!(hit.message_id)),
                        ("chatId", json!(chat_id)),
                        ("snippet", json!(hit.snippet)),
                        ("matchStart", json!(hit.match_start)),
                        ("matchLength", json!(hit.match_length)),
                        ("embedSourceLabel", meta_field(hit.meta, |m| &m.source_label)),
                        ("embedId", meta_field(hit.meta, |m| &m.embed_id)),
                        ("embedType", meta_field(hit.meta, |m| &m.embed_type)),
                        ("embedAppId", meta_field(hit.meta, |m| &m.app_id)),
                        ("embedSkillId", meta_field(hit.meta, |m| &m.skill_id)),
                        ("embedFocusId", meta_field(hit.meta, |m| &m.focus_id)),
                        ("embedFocusModeName", meta_field(hit.meta, |m| &m.focus_mode_name)),
                        ("embedFocusIsActive", hit.focus_active.map_or(Value::Null, Value::Bool)),
                    ])).collect::<Vec<_>>(),
                    "metadataSnippets": chat.metadata.iter().map(|hit| json!({
                        "chatId": chat_id,
                        "snippet": hit.snippet,
                        "matchStart": hit.match_start,
                        "matchLength": hit.match_length,
                        "matchSource": match hit.source { MetadataSource::Summary => "summary", MetadataSource::Tags => "tags", MetadataSource::Draft => "draft" },
                    })).collect::<Vec<_>>(),
                })
            }).collect::<Vec<_>>(),
            "embeds": outcome.embeds.iter().map(|embed| object(vec![
                ("embedId", json!(embed.embed_id)),
                ("embedType", json!(embed.embed_type)),
                ("chatId", json!(chat_ids[embed.position])),
                ("messageId", json!(embed.message_id)),
                ("title", json!(embed.title)),
                ("subtitle", json!(embed.subtitle)),
                ("appId", embed.app_id.map_or(Value::Null, |id| json!(id))),
                ("createdAt", json!(embed.created_at)),
            ])).collect::<Vec<_>>(),
            "settings": outcome.settings,
            "apps": outcome.apps.iter().map(|at| at - settings_count).collect::<Vec<_>>(),
        });
        // createdAt is integral in the fixtures; serde writes 110.0 as 110.0, JS as 110.
        let expected = normalize(case["expected"].clone());
        assert_eq!(normalize(actual), expected, "query {:?}", case["query"]);
    }
}

/// Integral floats compare equal to JSON integers.
fn normalize(value: Value) -> Value {
    match value {
        Value::Number(number) => match number.as_f64() {
            Some(float) if float.fract() == 0.0 && float.abs() < 1e15 => json!(float as i64),
            _ => Value::Number(number),
        },
        Value::Array(items) => Value::Array(items.into_iter().map(normalize).collect()),
        Value::Object(fields) => Value::Object(
            fields
                .into_iter()
                .map(|(key, value)| (key, normalize(value)))
                .collect(),
        ),
        other => other,
    }
}

fn columns<'a>(
    handles: &'a [u32],
    masks: &'a [u8],
    values: &[&str],
    tag_counts: &'a [u32],
    last_edited: &'a [f64],
) -> QueryColumns<'a> {
    QueryColumns {
        query: "q",
        flags: FLAG_INCLUDE_EMBEDS,
        handles,
        chat_masks: masks,
        chat_values: values.iter().map(|value| (*value).to_owned()).collect(),
        tag_counts,
        last_edited,
        catalog_flags: &[],
        catalog_labels: Vec::new(),
        catalog_keyword_counts: &[],
        catalog_keywords: Vec::new(),
    }
}

#[test]
fn from_wire_decodes_masks_and_tags_last() {
    let request = SearchQuery::from_wire(columns(
        &[7, 0],
        &[1 | 4 | 16, 2 | 8],
        &["Title", "S", "x", "y", "f", "D"],
        &[2, 0],
        &[9.0, 8.0],
    ))
    .unwrap();
    assert_eq!(request.chats[0].title.as_deref(), Some("Title"));
    assert_eq!(request.chats[0].summary.as_deref(), Some("S"));
    assert_eq!(
        request.chats[0].tags,
        Some(vec!["x".to_owned(), "y".to_owned()])
    );
    assert_eq!(request.chats[1].active_focus_id.as_deref(), Some("f"));
    assert_eq!(request.chats[1].draft.as_deref(), Some("D"));
    assert_eq!(request.chats[1].tags, None);
    assert!(request.include_embeds && !request.authenticated);
    assert_eq!(request.handles(), vec![7]);
}

#[test]
fn from_wire_refuses_inconsistent_columns() {
    let refused = |columns: QueryColumns<'_>| SearchQuery::from_wire(columns).unwrap_err().code();
    // Length mismatch, unknown mask bit, missing value, trailing value, tag count without the tag bit.
    assert_eq!(
        refused(columns(&[1, 2], &[0], &[], &[0, 0], &[0.0, 0.0])),
        "protocol"
    );
    assert_eq!(refused(columns(&[1], &[32], &[], &[0], &[0.0])), "protocol");
    assert_eq!(refused(columns(&[1], &[1], &[], &[0], &[0.0])), "protocol");
    assert_eq!(
        refused(columns(&[1], &[1], &["a", "b"], &[0], &[0.0])),
        "protocol"
    );
    assert_eq!(
        refused(columns(&[1], &[0], &["a"], &[1], &[0.0])),
        "protocol"
    );
    let mut bad_flags = columns(&[], &[], &[], &[], &[]);
    bad_flags.flags = 8;
    assert_eq!(refused(bad_flags), "protocol");
    let mut bad_catalog = columns(&[], &[], &[], &[], &[]);
    bad_catalog.catalog_flags = &[3];
    bad_catalog.catalog_labels = vec!["x".into()];
    bad_catalog.catalog_keyword_counts = &[0];
    assert_eq!(refused(bad_catalog), "protocol");
}

#[test]
fn encoded_rows_follow_the_documented_layout() {
    let mut index = ChatSearchIndex::default();
    let meta = EntryMeta {
        embed_id: Some("e1".into()),
        embed_type: Some("docs".into()),
        title: Some("Needle doc".into()),
        ..EntryMeta::default()
    };
    index.ingest_chat(
        1,
        vec![
            IngestEntry {
                message_id: "m1".into(),
                content: "a needle".into(),
                created_at: 5.0,
                meta: None,
            },
            IngestEntry {
                message_id: "m1".into(),
                content: "doc needle".into(),
                created_at: 5.0,
                meta: Some(meta),
            },
        ],
    );
    let request = SearchQuery {
        query: "needle".into(),
        include_embeds: true,
        chats: vec![QueryChat {
            handle: 1,
            last_edited: 1.0,
            ..QueryChat::default()
        }],
        catalog: vec![CatalogEntry {
            kind: CatalogKind::App,
            access: CatalogAccess::Public,
            label: "Needle app".into(),
            keywords: Vec::new(),
        }],
        ..SearchQuery::default()
    };
    let outcome = run_search(&index, &request);
    let encoded = outcome.encode();
    let rows = &encoded.rows;
    // Header: chats, embeds, settings hits, app hits.
    assert_eq!(&rows[..4], &[1, 1, 0, 1]);
    // Chat: position, ranges, message snippets, metadata snippets.
    assert_eq!(&rows[4..8], &[0, 0, 2, 0]);
    let after_chat = 8 + 2 * MESSAGE_SNIPPET_WORDS;
    assert_eq!(rows[after_chat], 0, "embed chat position");
    assert_eq!(rows[after_chat + EMBED_WORDS], 0, "app catalog index");
    assert_eq!(rows.len(), after_chat + EMBED_WORDS + 1);
    assert_eq!(encoded.numbers, vec![5.0]);
    let snippet_focus = rows[8 + MESSAGE_SNIPPET_WORDS - 1];
    assert_eq!(snippet_focus, FOCUS_NONE);
}
